"""Meeting Rooms II — min-heap of end times (one entry per busy room).

If the earliest-finishing room is already free when the next meeting starts, it
is reused; otherwise a new room is opened.

Time: O(n log n)   Space: O(n)
"""
import heapq
from typing import List


class Solution:
    def minMeetingRooms(self, intervals: List[List[int]]) -> int:
        if not intervals:
            return 0
        intervals.sort()
        rooms = []
        for start, end in intervals:
            if rooms and rooms[0] <= start:
                heapq.heapreplace(rooms, end)
            else:
                heapq.heappush(rooms, end)
        return len(rooms)
